<script setup>
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {api,session} from '../../services/api.js'
const props=defineProps({policy:Object,graph:Object,nodes:Array,editable:Boolean,baseVersionId:String})
const kind=ref('historical'),hours=ref(24),nodeIds=ref([]),jobs=ref([]),selected=ref(null),results=ref({items:[],total:0}),page=ref(1),outcome=ref(''),reason=ref(''),error=ref(''),busy=ref(false)
const contextMessage=ref('')
async function captureContext(){busy.value=true;error.value='';contextMessage.value='';let collected=0;try{for(const id of nodeIds.value){const node=props.nodes.find(n=>n.id===id);if(!['winrm','winrms'].includes(node?.transport))continue;contextMessage.value=`Reading effective policy from ${node.hostname}…`;await api(`/nodes/${id}/policy-context`,{method:'POST',body:{}});collected++}contextMessage.value=`Captured effective policy from ${collected} Windows assets. Start an evaluation within five minutes to pin this context.`}catch(e){error.value=e.message}finally{busy.value=false}}
let timer
async function load(){try{jobs.value=await api(`/policies/${props.policy.id}/simulations`);if(selected.value){selected.value=jobs.value.find(j=>j.id===selected.value.id)||null;await details()}}catch(e){error.value=e.message}}
async function details(){if(!selected.value)return;results.value=await api(`/policy-simulations/${selected.value.id}/results?`+new URLSearchParams({page:page.value,pageSize:25,...(outcome.value?{outcome:outcome.value}:{})}))}
async function choose(job){selected.value=job;page.value=1;outcome.value='';try{await details()}catch(e){error.value=e.message}}
async function start(){busy.value=true;error.value='';try{const stamp=Date.now(),span=hours.value*3600000;selected.value=await api(`/policies/${props.policy.id}/simulations`,{method:'POST',body:{graph:props.graph,baseVersionId:props.baseVersionId??null,nodeIds:nodeIds.value,kind:kind.value,from:new Date(kind.value==='historical'?stamp-span:stamp).toISOString(),to:new Date(kind.value==='historical'?stamp:stamp+span).toISOString()}});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function action(name){busy.value=true;error.value='';try{selected.value=await api(`/policy-simulations/${selected.value.id}/${name}`,{method:'POST',body:{reason:reason.value}});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
watch(()=>props.policy.id,()=>{selected.value=null;nodeIds.value=[];load()})
onMounted(()=>{load();timer=setInterval(()=>{if(jobs.value.some(j=>['queued','running','observing'].includes(j.status)))load()},3000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel glass simulation-panel"><div class="panel-title"><h2>Policy impact</h2><button class="button secondary" @click="load">Refresh</button></div><div class="simulation-body"><p class="muted">Replay a pinned draft against historical traffic or observe new traffic. Simulation does not install rules. Missing telemetry and unsupported firewall behavior remain indeterminate.</p><p v-if="error" class="error-msg" role="alert">{{error}}</p><form v-if="editable" class="simulation-form" @submit.prevent="start"><label>Evaluation<select v-model="kind"><option value="historical">Historical replay</option><option value="observe">Observe only</option></select></label><label>Window (hours)<input v-model.number="hours" type="number" min="0.05" :max="kind==='observe'?24:720" step="0.05" required></label><label>Target assets<select v-model="nodeIds" multiple required aria-label="Simulation target assets"><option v-for="n in nodes" :key="n.id" :value="n.id">{{n.hostname}} · {{n.ip}}</option></select></label><button v-if="['owner','admin'].includes(session.user?.role)" type="button" class="button secondary" :disabled="busy||!nodeIds.length" @click="captureContext">Read effective host policy</button><button class="button primary" :disabled="busy||!nodeIds.length">Start evaluation</button></form><p v-if="contextMessage" role="status">{{contextMessage}}</p><div class="table-wrap"><table><thead><tr><th>Started</th><th>Mode</th><th>Status</th><th>Observations</th><th>Review</th><th></th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{new Date(job.created_at).toLocaleString()}}</td><td>{{job.kind}}</td><td>{{job.status}}</td><td>{{job.processed}}</td><td>{{job.stale?'Stale — policy or targets changed':job.approvalValid?'Reviewed':'Awaiting review'}}</td><td><button class="button small secondary" @click="choose(job)">Details</button></td></tr><tr v-if="!jobs.length"><td colspan="6">No evaluations yet.</td></tr></tbody></table></div><template v-if="selected"><h3>Evaluation details</h3><p>{{Object.entries(selected.summary||{}).map(([key,count])=>`${key}: ${count}`).join(' · ')}}</p><p v-if="!selected.processed" class="muted">No matching traffic has been evaluated. This is not proof that the draft is safe.</p><div class="simulation-actions"><select v-model="outcome" aria-label="Impact outcome" @change="page=1;details()"><option value="">All outcomes</option><option v-for="o in ['newly-allowed','newly-blocked','unchanged','indeterminate']" :key="o">{{o}}</option></select><button v-if="editable&&['queued','running','observing'].includes(selected.status)" class="button secondary" :disabled="busy" @click="action('cancel')">Cancel evaluation</button><template v-if="['owner','admin'].includes(session.user?.role)&&selected.status==='completed'&&!selected.stale"><input v-model="reason" placeholder="Review reason" maxlength="1000" aria-label="Simulation review reason"><button class="button secondary" :disabled="busy||!reason.trim()" @click="action('approve')">Record review</button></template></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Source → destination</th><th>Application</th><th>Outcome</th><th>Explanation / matching rules</th></tr></thead><tbody><tr v-for="r in results.items" :key="r.eventId"><td>{{r.flow.time}}</td><td>{{r.flow.sourceIp}} → {{r.flow.destinationIp}}:{{r.flow.destinationPort}}</td><td>{{r.flow.program||'Not captured'}}</td><td>{{r.outcome}}</td><td>{{r.reason}}<small>{{r.after.rules.join(', ')}}</small></td></tr></tbody></table></div><div class="simulation-actions"><span>{{results.total}} observations · Page {{page}}</span><button class="button secondary" :disabled="page===1" @click="page--;details()">Previous</button><button class="button secondary" :disabled="page*25>=results.total" @click="page++;details()">Next</button></div></template></div></section></template>
<style scoped>.simulation-body{padding:16px;min-width:0}.simulation-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:end;margin:16px 0}.simulation-form label{display:grid;gap:6px}.simulation-actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:16px 0}.table-wrap{max-width:100%;overflow:auto}table{width:100%}td{max-width:45ch;overflow-wrap:anywhere}small{display:block;color:var(--muted)}@media(max-width:850px){.simulation-form{grid-template-columns:1fr}}</style>
